	@Test
	void singletonCapturedContextBorrowsParentViewAcrossNestedScope(@TempDir Path directory) throws Exception {
		LmdbStore store = initializedStore(directory);
		LmdbSailStore backingStore = store.getBackingStore();
		LmdbSailStore.MapGrowthObserver observer = (kind, token, deadlineNanos, attempts, views) -> false;
		LmdbSailStore.ReadAttemptLease attempt = backingStore.registerReadAttempt(observer);
		LmdbSailStore.ReadView parentView;
		LmdbSailStore.ReadViewLease parentLease;
		try (LmdbSailStore.DatasetAdmission admission = backingStore.beginDatasetAdmission(
				IsolationLevels.READ_COMMITTED, null, observer, attempt)) {
			parentView = admission.view().retain();
			parentLease = admission.readViewLease();
		}
		AtomicReference<LmdbSailStore.ReadViewLease> expectedLease = new AtomicReference<>(parentLease);
		AtomicInteger expectedTripleSlots = new AtomicInteger();
		AtomicInteger expectedValueSlots = new AtomicInteger();
		AtomicInteger delegateCalls = new AtomicInteger();
		TxnManager triples = backingStore.getTripleStore().getTxnManager();
		TxnManager values = ((ValueStore) backingStore.getValueFactory()).getTxnManager();
		SketchStatementSource delegate = statementSource((subject, predicate, object, contexts) -> {
			assertSame(expectedLease.get(), backingStore.currentReadViewLease(),
					"The estimator source must temporarily bind the captured singleton paired view");
			assertEquals(expectedTripleSlots.get(), triples.availableReadTxnSlots(Integer.MAX_VALUE, 0),
					"Borrowing a captured TripleStore view must not reserve another reader slot");
			assertEquals(expectedValueSlots.get(), values.availableReadTxnSlots(Integer.MAX_VALUE, 0),
					"Borrowing a captured ValueStore view must not reserve another reader slot");
			delegateCalls.incrementAndGet();
			return emptyIteration(() -> {
			});
		});
		LmdbSailStore.GuardedEstimatorStatementSource source = backingStore.new GuardedEstimatorStatementSource(
				delegate);
		try (SailClosable outer = backingStore.enterCapturedReadViews(attempt, attempt.generation(),
				List.of(parentLease), null)) {
			assertNull(backingStore.currentReadViewLease(),
					"A null-preferred capture must remain unbound until a source borrows its singleton");
			expectedTripleSlots.set(triples.availableReadTxnSlots(Integer.MAX_VALUE, 0));
			expectedValueSlots.set(values.availableReadTxnSlots(Integer.MAX_VALUE, 0));
			try (SailClosable nestedEmpty = backingStore.enterCapturedReadViews(attempt, attempt.generation(),
					List.of(), null);
					CloseableIteration<? extends Statement> statements = source.getStatements(null, null, null)) {
				assertFalse(statements.hasNext());
			}
			assertNull(backingStore.currentReadViewLease(),
					"Closing the nested empty capture must restore the outer unbound context");
			try (CloseableIteration<? extends Statement> statements = source.getStatements(null, null, null)) {
				assertFalse(statements.hasNext());
			}
			assertEquals(2, delegateCalls.get(),
					"The nested and restored scopes must both borrow the one parent-owned paired view");
		} finally {
			parentView.close();
			attempt.close();
			store.shutDown();
		}
	}

