	@Test
	void ordinaryConnectionReadScopeBorrowsItsUnboundViewForEstimatorLookup(@TempDir Path directory) throws Exception {
		LmdbStore store = initializedStore(directory);
		LmdbSailStore backingStore = store.getBackingStore();
		Object owner = new Object();
		try (SailSource writeSource = backingStore.getExplicitSailSource(owner);
				SailClosable publication = writeSource.beginPublication(owner);
				SailSink sink = writeSource.sink(IsolationLevels.NONE)) {
			sink.approve(SUBJECT, PREDICATE, OBJECT, null);
			sink.approve(NAMED_SUBJECT, PREDICATE, OBJECT, NAMED_CONTEXT);
			sink.setNamespace("admission", "urn:publication-admission:");
			sink.setNamespace("admission-named", "urn:publication-admission:named:");
			sink.flush();
		}
		TxnManager triples = backingStore.getTripleStore().getTxnManager();
		TxnManager values = ((ValueStore) backingStore.getValueFactory()).getTxnManager();
		SketchStatementSource nativeDelegate = new SailStoreStatementSource(backingStore);
		AtomicReference<LmdbSailStore.ReadViewLease> expectedOwnedLease = new AtomicReference<>();
		SketchStatementSource observedDelegate = statementSource((subject, predicate, object, contexts) -> {
			assertSame(expectedOwnedLease.get(), backingStore.currentReadViewLease(),
					"The real guarded source must bind the exact connection-owned paired view for its delegate");
			return nativeDelegate.getStatements(subject, predicate, object, contexts);
		});
		LmdbSailStore.GuardedEstimatorStatementSource source = backingStore.new GuardedEstimatorStatementSource(
				observedDelegate);
		Map<Statement, Integer> expectedStatements = Map.of(
				VALUES.createStatement(SUBJECT, PREDICATE, OBJECT), 1,
				VALUES.createStatement(NAMED_SUBJECT, PREDICATE, OBJECT, NAMED_CONTEXT), 1);
		try (QueryCallbackConnection connection = new QueryCallbackConnection(store)) {
			connection.inReadScope(() -> {
				assertNull(backingStore.currentReadViewLease(),
						"The connection callback starts without a dataset-bound view");
				Map<Statement, Integer> queryStatements = new HashMap<>();
				try (CloseableIteration<? extends Statement> query = connection.getStatements(null, null, null, true)) {
					assertTrue(query.hasNext(), "The ordinary connection lookup must produce the published rows");
					queryStatements.merge(query.next(), 1, Integer::sum);
					assertNull(backingStore.currentReadViewLease(),
							"The ordinary dataset acquisition must unbind its paired view before the callback continues");
					List<LmdbSailStore.ReadViewLease> resourceViews = backingStore.currentReadResourceViews();
					assertEquals(1, resourceViews.size(),
							"The foreground read callback must expose its single owned paired view through scoped context");
					expectedOwnedLease.set(resourceViews.get(0));
					int availableTripleSlots = triples.availableReadTxnSlots(Integer.MAX_VALUE, 0);
					int availableValueSlots = values.availableReadTxnSlots(Integer.MAX_VALUE, 0);
					Map<Statement, Integer> estimatorStatements = new HashMap<>();
					try (CloseableIteration<? extends Statement> estimatorRead = source.getStatements(null, null,
							null)) {
						assertNull(backingStore.currentReadViewLease(),
								"The guarded source must restore the caller's unbound dataset state");
						while (estimatorRead.hasNext()) {
							estimatorStatements.merge(estimatorRead.next(), 1, Integer::sum);
						}
						assertEquals(availableTripleSlots, triples.availableReadTxnSlots(Integer.MAX_VALUE, 0),
								"The estimator lookup must reuse the query's paired TripleStore snapshot");
						assertEquals(availableValueSlots, values.availableReadTxnSlots(Integer.MAX_VALUE, 0),
								"The estimator lookup must reuse the query's paired ValueStore snapshot");
					}
					assertEquals(expectedStatements, estimatorStatements,
							"The actual guarded source must preserve the exact default and named-context statement bag");
					while (query.hasNext()) {
						queryStatements.merge(query.next(), 1, Integer::sum);
					}
				}
				assertEquals(expectedStatements, queryStatements,
						"The ordinary SailConnection lookup must preserve the exact statement bag");
				return null;
			});
		} finally {
			store.shutDown();
		}
	}

	@ParameterizedTest
	@EnumSource(CallbackFailure.class)
	void realConnectionCallbackFailureRestoresReadResourcesAndAllowsLaterLookup(CallbackFailure kind,
			@TempDir Path directory) throws Exception {
		LmdbStore store = initializedStore(directory);
		awaitReadAdmissionFixtureSetup(store);
		LmdbSailStore backingStore = store.getBackingStore();
		Object owner = new Object();
		try (SailSource writeSource = backingStore.getExplicitSailSource(owner);
				SailClosable publication = writeSource.beginPublication(owner);
				SailSink sink = writeSource.sink(IsolationLevels.NONE)) {
			sink.approve(SUBJECT, PREDICATE, OBJECT, null);
			sink.approve(NAMED_SUBJECT, PREDICATE, OBJECT, NAMED_CONTEXT);
			sink.setNamespace("admission", "urn:publication-admission:");
			sink.setNamespace("admission-named", "urn:publication-admission:named:");
			sink.flush();
		}
		Map<Statement, Integer> expectedStatements = Map.of(
				VALUES.createStatement(SUBJECT, PREDICATE, OBJECT), 1,
				VALUES.createStatement(NAMED_SUBJECT, PREDICATE, OBJECT, NAMED_CONTEXT), 1);
		TxnManager triples = backingStore.getTripleStore().getTxnManager();
		TxnManager values = ((ValueStore) backingStore.getValueFactory()).getTxnManager();
		try (QueryCallbackConnection connection = new QueryCallbackConnection(store)) {
			int initialTripleSlots = triples.availableReadTxnSlots(Integer.MAX_VALUE, 0);
			int initialValueSlots = values.availableReadTxnSlots(Integer.MAX_VALUE, 0);
			Throwable expectedFailure = kind.failure();
			Throwable actualFailure = assertThrows(Throwable.class, () -> connection.inReadScope(() -> {
				Map<Statement, Integer> observedStatements = new HashMap<>();
				try (CloseableIteration<? extends Statement> statements = connection.getStatements(null, null, null,
						true)) {
					while (statements.hasNext()) {
						observedStatements.merge(statements.next(), 1, Integer::sum);
					}
				}
				assertEquals(expectedStatements, observedStatements,
						"The failing callback must exercise a real, complete LMDB statement lookup");
				assertEquals(1, backingStore.currentReadResourceViews().size(),
						"The callback must own its view through the active foreground resource context");
				if (expectedFailure instanceof RuntimeException runtimeFailure) {
					throw runtimeFailure;
				}
				throw (Error) expectedFailure;
			}));
			assertSame(expectedFailure, actualFailure, "The real callback failure identity must be preserved");
			assertTrue(backingStore.currentReadResourceViews().isEmpty(),
					"A failed connection callback must restore the prior read-resource context");
			assertNull(backingStore.currentReadViewLease(),
					"A failed connection callback must not leave a temporary dataset binding installed");
			assertEquals(initialTripleSlots, triples.availableReadTxnSlots(Integer.MAX_VALUE, 0),
					"A failed callback must return all ordinary TripleStore reader slots");
			assertEquals(initialValueSlots, values.availableReadTxnSlots(Integer.MAX_VALUE, 0),
					"A failed callback must return all ordinary ValueStore reader slots");

			Map<Statement, Integer> laterStatements = new HashMap<>();
			try (CloseableIteration<? extends Statement> statements = connection.getStatements(null, null, null,
					true)) {
				while (statements.hasNext()) {
					laterStatements.merge(statements.next(), 1, Integer::sum);
				}
			}
			assertEquals(expectedStatements, laterStatements,
					"A fresh lookup on the same connection must progress after callback cleanup");
			Map<String, String> actualNamespaces = new HashMap<>();
			try (CloseableIteration<? extends Namespace> namespaces = connection.getNamespaces()) {
				while (namespaces.hasNext()) {
					Namespace namespace = namespaces.next();
					actualNamespaces.put(namespace.getPrefix(), namespace.getName());
				}
			}
			assertEquals(Map.of(
					"admission", "urn:publication-admission:",
					"admission-named", "urn:publication-admission:named:"), actualNamespaces,
					"The post-failure namespace lookup must remain complete and exact");
		} finally {
			store.shutDown();
		}
	}

